438	// canonicalRule is the order-independent view of a rule used for the id. The
439	// note is omitted when empty so reports built only from invariant booleans
440	// keep their original ids.
441	type canonicalRule struct {
442		ID          string `json:"id"`
443		Kind        string `json:"kind"`
444		Severity    string `json:"severity"`
445		Invariant   string `json:"invariant"`
446		RequiresABI bool   `json:"requiresABI"`
447		Version     string `json:"version"`
448		Status      string `json:"status"`
449		Note        string `json:"note,omitempty"`
450	}
451	
452	// canonicalFinding is the order-independent view of a finding used for the id.
453	type canonicalFinding struct {
454		ArtifactHash string `json:"artifactHash"`
455		RuleID       string `json:"ruleId"`
456		Version      string `json:"version"`
457		Severity     string `json:"severity"`
458		Invariant    string `json:"invariant"`
459		Evidence     string `json:"evidence"`
460	}
461	
462	// canonicalReport is the deterministic content a report id is computed from.
463	type canonicalReport struct {
464		ArtifactHash string             `json:"artifactHash"`
465		Name         string             `json:"name"`
466		Rules        []canonicalRule    `json:"rules"`
467		Findings     []canonicalFinding `json:"findings"`
468	}
469	
470	// canonicalize renders a report into its order-independent form.
471	func canonicalize(report Report) canonicalReport {
472		cr := canonicalReport{
473			ArtifactHash: report.Artifact.Hash,
474			Name:         report.Artifact.Name,
475		}
476		for _, rule := range report.Rules {
477			cr.Rules = append(cr.Rules, canonicalRule{
478				ID: rule.ID, Kind: rule.Kind, Severity: rule.Severity,
479				Invariant: rule.Invariant, RequiresABI: rule.RequiresABI,
480				Version: rule.Version, Status: rule.Status, Note: rule.Note,
481			})
482		}
483		sort.Slice(cr.Rules, func(i, j int) bool { return cr.Rules[i].ID < cr.Rules[j].ID })
484		for _, finding := range report.Findings {
485			cr.Findings = append(cr.Findings, canonicalFinding{
486				ArtifactHash: finding.ArtifactHash, RuleID: finding.RuleID,
487				Version: finding.Version, Severity: finding.Severity,
488				Invariant: finding.Invariant, Evidence: finding.Evidence,
489			})
490		}
491		sort.Slice(cr.Findings, func(i, j int) bool { return cr.Findings[i].RuleID < cr.Findings[j].RuleID })
492		return cr
493	}
494	
495	// ReportID returns the content-addressed identifier of a report. The id binds
496	// the artifact hash, name, complete rule definitions, the invariant value
497	// used by each rule (unchecked and explicit pass are distinct), and the
498	// findings. Rule order, invariant key order and unrelated invariant keys do
499	// not influence it.
500	func ReportID(r Report) string {
501		data, err := json.Marshal(canonicalize(r))
502		if err != nil {
503			panic(err) // canonical values are all strings and bools
504		}
505		sum := sha256.Sum256(data)
506		return hex.EncodeToString(sum[:])
507	}
508	
509	// validateReport checks every archive legality condition against r. It is the
510	// single definition of a legal report: the id and artifact hash are 64
511	// lowercase hex characters, the id matches the content, the artifact name is
512	// present, rule ids are present and unique with non-empty versions, statuses
513	// use the five recorded values, tool-missing and timeout notes are
514	// non-blank, and 发现缺陷 rules correspond one-to-one with findings whose
515	// artifact hash, version, severity, invariant and evidence match the rule.
516	// The same conditions apply to submissions and to stored archives: a
517	// recomputed id never makes an invalid report legal. fail is errInvalid for
518	// submissions and errCorrupt for stored archives.
519	func validateReport(r Report, fail func(string) error) error {
520		if !validReportID(r.ReportID) {
521			return fail("report id " + r.ReportID + " is not a 64-character lowercase hex string")
522		}
523		if r.Artifact.Name == "" {
524			return fail("report " + r.ReportID + " artifact name is required")
525		}
526		if !validReportID(r.Artifact.Hash) {
527			return fail("report " + r.ReportID + " artifact hash is not a 64-character lowercase hex string")
528		}
529		if ReportID(r) != r.ReportID {
530			return fail("report content does not match id " + r.ReportID)
531		}
532		seenRule := make(map[string]bool, len(r.Rules))
533		defectByID := make(map[string]ReportRule)
534		for _, rule := range r.Rules {
535			if rule.ID == "" {
536				return fail("report " + r.ReportID + " has a rule with an empty id")
537			}
538			if seenRule[rule.ID] {
539				return fail("report " + r.ReportID + " has duplicate rule id " + rule.ID)
540			}
541			seenRule[rule.ID] = true
542			if rule.Version == "" {
543				return fail("report " + r.ReportID + " rule " + rule.ID + " has an empty version")
544			}
545			switch rule.Status {
546			case StatusUnchecked, StatusPass, StatusDefect, StatusToolMissing, StatusTimeout:
547			default:
548				return fail("report " + r.ReportID + " rule " + rule.ID + " has unknown status " + rule.Status)
549			}
550			if (rule.Status == StatusToolMissing || rule.Status == StatusTimeout) && strings.TrimSpace(rule.Note) == "" {
551				return fail("report " + r.ReportID + " rule " + rule.ID + " status " + rule.Status + " has no note")
552			}
553			if rule.Status == StatusDefect {
554				defectByID[rule.ID] = rule
555			}
556		}
557		seenFinding := make(map[string]bool, len(r.Findings))
558		for _, f := range r.Findings {
559			if f.RuleID == "" {
560				return fail("report " + r.ReportID + " has a finding with an empty rule id")
561			}
562			rule, ok := defectByID[f.RuleID]
563			if !ok {
564				return fail("report " + r.ReportID + " finding for rule " + f.RuleID + " does not match a 发现缺陷 rule")
565			}
566			if seenFinding[f.RuleID] {
567				return fail("report " + r.ReportID + " has a duplicate finding for rule " + f.RuleID)
568			}
569			seenFinding[f.RuleID] = true
570			if f.ArtifactHash != r.Artifact.Hash {
571				return fail("report " + r.ReportID + " finding for rule " + f.RuleID + " has artifact hash " + f.ArtifactHash + ", want " + r.Artifact.Hash)
572			}
573			if f.Version != rule.Version {
574				return fail("report " + r.ReportID + " finding for rule " + f.RuleID + " has version " + f.Version + ", want " + rule.Version)
575			}
576			if f.Severity != rule.Severity {
577				return fail("report " + r.ReportID + " finding for rule " + f.RuleID + " has severity " + f.Severity + ", want " + rule.Severity)
578			}
579			if f.Invariant != rule.Invariant {
580				return fail("report " + r.ReportID + " finding for rule " + f.RuleID + " has invariant " + f.Invariant + ", want " + rule.Invariant)
581			}
582			wantEvidence := rule.Note
583			if wantEvidence == "" {
584				wantEvidence = "invariant " + rule.Invariant + " does not hold"
585			}
586			if f.Evidence != wantEvidence {
587				return fail("report " + r.ReportID + " finding for rule " + f.RuleID + " has evidence " + f.Evidence + ", want " + wantEvidence)
588			}
589		}
590		for id := range defectByID {
591			if !seenFinding[id] {
592				return fail("report " + r.ReportID + " defect rule " + id + " has no finding")
593			}
594		}
595		return nil
596	}
