675	// duplicateArchiveError classifies an archive that repeats a JSON member as
676	// corrupt and names the requested report id, the decoded member name and the
677	// object carrying it (with array position and rule id when applicable).
678	func duplicateArchiveError(id string, data []byte, dup *duplicateMemberError) error {
679		return errCorrupt("report " + id + " archive is corrupt: " + duplicateMemberMessage(data, dup))
680	}
681	
682	// characterArchiveError classifies an archive whose bytes are not legal JSON
683	// text — an invalid UTF-8 byte anywhere, or an unpaired / wrongly ordered
684	// surrogate escape inside any member name or string value, including unknown
685	// extension members — as corrupt and names the requested report id together
686	// with the precise byte offset, line/column and JSON path. It is the
687	// read-side counterpart of the submission gate in ParseAuditInput: the decode
688	// below would otherwise replace both problems with U+FFFD and could accept a
689	// rewritten archive whose id and rule/finding evidence happened to match.
690	func characterArchiveError(id string, charErr *charEncodingError) error {
691		return errCorrupt("report " + id + " archive is corrupt: " + charErr.Error())
692	}
693	
694	// reportShape is the fixed-field shape of a stored report archive: the agreed
695	// spellings at the top level and inside the artifact, every rule and every
696	// finding. The trusted content of a report is carried by these fixed fields
697	// alone; case variants, whitespace-padded names and unknown members are
698	// extension data and never reach the decoder.
699	var reportShape = fixedShape{
700		keys: []string{"reportId", "artifact", "rules", "findings"},
701		objects: map[string]fixedShape{
702			"artifact": {keys: []string{"name", "hash"}},
703		},
704		arrays: map[string]fixedShape{
705			"rules":    {keys: []string{"id", "kind", "severity", "invariant", "requiresABI", "version", "status", "note"}},
706			"findings": {keys: []string{"artifactHash", "ruleId", "version", "severity", "invariant", "evidence"}},
707		},
708	}
709	
710	// strictReportJSON rewrites archive bytes to the fixed report fields under
711	// their original spelling; see fixedShape for the recognition convention
712	// shared with the submission side.
713	func strictReportJSON(data []byte) ([]byte, error) {
714		return strictFixedJSON(data, reportShape)
715	}
716	
717	// validateArchiveRequiresABI is the read-side counterpart of the submission
718	// check in validateFormalRequiresABI. A ReportRule.RequiresABI is a Go bool,
719	// so decoding the strict archive straight into Report turns a formal null
720	// member into the zero value false: an archive that wrote "requiresABI":null
721	// would read byte-for-byte like one that wrote false, the recomputed id and
722	// the rule/finding correspondence would all pass on that laundered value, and
723	// a diff could even compare it as an unchanged rule. When the formal member
724	// is present its value must therefore be the JSON boolean true or false;
725	// null, a string, a number, an object or an array makes the whole archive
726	// corrupt, independently of the rule's check status and of whether it has a
727	// finding — the offending rule is never skipped and no partial report is
728	// returned. An omitted member still means false. The strict rewrite dropped
729	// extension members, so a case-variant or whitespace-padded name is invisible
730	// here: a boolean it carries neither supplies nor rescues the formal value,
731	// and a null it carries never reaches this check.
732	func validateArchiveRequiresABI(strict []byte, id string) error {
733		var top struct {
734			Rules []map[string]json.RawMessage `json:"rules"`
735		}
736		if err := json.Unmarshal(strict, &top); err != nil {
737			return errCorrupt("invalid JSON in report " + id + ": " + err.Error())
738		}
739		for _, rule := range top.Rules {
740			where := "rule"
741			if raw, ok := rule["id"]; ok {
742				var ruleID string
743				if err := json.Unmarshal(raw, &ruleID); err == nil && ruleID != "" {
744					where = "rule " + ruleID
745				}
746			}
747			raw, ok := rule["requiresABI"]
748			if !ok {
749				continue
750			}
751			var token any
752			if err := json.Unmarshal(raw, &token); err != nil {
753				return errCorrupt("report " + id + " archive is corrupt: " + where + ": requiresABI must be a boolean")
754			}
755			if _, isBool := token.(bool); !isBool {
756				return errCorrupt("report " + id + " archive is corrupt: " + where + ": requiresABI must be a boolean")
757			}
758		}
759		return nil
760	}
761	
762	// loadStoredReport parses archive bytes for id and fully validates them.
763	func loadStoredReport(data []byte, id string) (Report, error) {
764		// Read-side counterpart of the submission character gate in
765		// ParseAuditInput. As with a repeated member, json.Unmarshal silently
766		// rewrites an invalid UTF-8 byte and an unpaired or wrongly ordered
767		// surrogate escape into U+FFFD, so an archive whose note and evidence both
768		// carried the substitution character could have those two spots changed to
769		// lone surrogate escapes and still decode to byte-identical content: the
770		// recomputed id and the rule/finding evidence comparison would then pass on
771		// the rewritten copy. Every raw string literal is checked first — member
772		// names and values, at every depth, inside unknown extension members too —
773		// and the whole archive is corrupt when any character is illegal, whatever
774		// id the rewritten content would compute.
775		if charErr := validateJSONCharacters(data); charErr != nil {
776			return Report{}, characterArchiveError(id, charErr)
777		}
778		// Read-side counterpart of the submission check: json.Unmarshal silently
779		// keeps the last value for a repeated member, so an archive that writes a
780		// rule status as 发现缺陷 and then 通过 would decode to whichever came
781		// last. The recomputed id and the rule/finding correspondence all operate
782		// on that last-wins value and could therefore pass, accepting an archive
783		// with two conflicting conclusions. Any repeated member in any object
784		// makes the archive corrupt, regardless of the last value.
785		if dup := findDuplicateJSONMember(data); dup != nil {
786			return Report{}, duplicateArchiveError(id, data, dup)
787		}
788		strict, err := strictReportJSON(data)
789		if err != nil {
790			return Report{}, errCorrupt("invalid JSON in report " + id + ": " + err.Error())
791		}
792		// Check the formal requiresABI member against its raw JSON token before
793		// decoding into the Go bool below; otherwise a null value would silently
794		// become the zero value false and could pass every later check, including
795		// the content id, as if the archive had explicitly said false.
796		if err := validateArchiveRequiresABI(strict, id); err != nil {
797			return Report{}, err
798		}
799		var r Report
800		if err := json.Unmarshal(strict, &r); err != nil {
801			return Report{}, errCorrupt("invalid JSON in report " + id + ": " + err.Error())
802		}
803		if r.ReportID != id {
804			return Report{}, errCorrupt("report id " + r.ReportID + " does not match requested id " + id)
805		}
806		if err := validStoredReport(r); err != nil {
807			return Report{}, err
808		}
809		return r, nil
810	}
811	
812	// saveReportHook, when set, is invoked after the archive existence check and
813	// before the atomic publish. It lets tests simulate another process racing to
814	// claim the same report id.
815	var saveReportHook func(finalPath string)
816	
817	// SaveReport persists a report under the store directory. The store is safe
818	// for concurrent writers: identical reports share one file and all
819	// submissions succeed, different reports never overwrite each other, and
820	// readers only ever observe complete files. A submission is fully validated
821	// before any store operation, so an invalid report creates no store and no
822	// files. Every string in a directly constructed report must be valid UTF-8:
823	// json.Marshal would otherwise rewrite an invalid byte to U+FFFD while the
824	// content-addressed id matched the rewritten copy, reporting success for an
825	// archive whose text differs from the caller's; such a report is rejected as
826	// an input error before the store directory is touched. A pre-existing file
827	// with the same id must be a valid archive of the same report; a corrupted
828	// archive makes the submission fail while keeping the original file, even
829	// when the corruption appears only during the save. The first successfully
830	// archived bytes are never replaced by later submissions.
831	func SaveReport(dir string, r Report) error {
832		if err := validateSubmittedText(r); err != nil {
833			return err
834		}
835		if err := validSubmittedReport(r); err != nil {
836			return err
837		}
838		if err := os.MkdirAll(dir, 0o755); err != nil {
839			return err
840		}
841		finalPath := filepath.Join(dir, r.ReportID+".json")
842		if existing, err := os.ReadFile(finalPath); err == nil {
843			if _, err := loadStoredReport(existing, r.ReportID); err != nil {
844				return err
845			}
846			return nil
847		} else if !os.IsNotExist(err) {
848			return err
849		}
850		data, err := json.Marshal(r)
851		if err != nil {
852			return err
853		}
854		tmp, err := os.CreateTemp(dir, ".report-*.tmp")
855		if err != nil {
856			return err
857		}
858		tmpPath := tmp.Name()
859		cleanup := func() { os.Remove(tmpPath) }
860		if _, err := tmp.Write(data); err != nil {
861			tmp.Close()
862			cleanup()
863			return err
864		}
865		if err := tmp.Sync(); err != nil {
866			tmp.Close()
867			cleanup()
868			return err
869		}
870		if err := tmp.Close(); err != nil {
871			cleanup()
872			return err
873		}
874		if saveReportHook != nil {
875			saveReportHook(finalPath)
876		}
877		if err := os.Link(tmpPath, finalPath); err != nil {
878			cleanup()
879			if os.IsExist(err) {
880				existing, readErr := os.ReadFile(finalPath)
881				if readErr != nil {
882					return readErr
883				}
884				if _, err := loadStoredReport(existing, r.ReportID); err != nil {
885					return err
886				}
887				return nil
888			}
889			return err
890		}
891		cleanup()
892		return nil
893	}
894	
895	// LoadReport reads and verifies a report by id. The id must be 64 lowercase
896	// hex characters; missing, corrupted or tampered archives produce a clear
897	// error. The store is only read, never created or modified.
898	func LoadReport(dir, id string) (Report, error) {
899		if !validReportID(id) {
900			return Report{}, errInvalid("invalid report id " + id + ": want 64 lowercase hex characters")
901		}
902		data, err := os.ReadFile(filepath.Join(dir, id+".json"))
903		if err != nil {
904			if os.IsNotExist(err) {
905				return Report{}, errNotFound("report " + id + " not found")
906			}
907			return Report{}, err
908		}
909		return loadStoredReport(data, id)
910	}
911	
912	type errNotFound string
913	
914	func (e errNotFound) Error() string { return string(e) }
915	
916	type errCorrupt string
917	
918	func (e errCorrupt) Error() string { return string(e) }
919

